class Solution {
public:
    int largestMagicSquare(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> rowPref(m, vector<int>(n + 1, 0));
        vector<vector<int>> colPref(m + 1, vector<int>(n, 0));

        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                rowPref[r][c + 1] = rowPref[r][c] + grid[r][c];
                colPref[r + 1][c] = colPref[r][c] + grid[r][c];
            }
        }

        for (int k = min(m, n); k > 1; --k) {
            for (int r = 0; r <= m - k; ++r) {
                for (int c = 0; c <= n - k; ++c) {
                    int target = rowPref[r][c + k] - rowPref[r][c];
                    bool valid = true;

                    for (int i = 1; i < k; ++i) {
                        if (rowPref[r + i][c + k] - rowPref[r + i][c] != target) {
                            valid = false;
                            break;
                        }
                    }
                    if (!valid) continue;

                    for (int j = 0; j < k; ++j) {
                        if (colPref[r + k][c + j] - colPref[r][c + j] != target) {
                            valid = false;
                            break;
                        }
                    }
                    if (!valid) continue;

                    int d1 = 0, d2 = 0;
                    for (int i = 0; i < k; ++i) {
                        d1 += grid[r + i][c + i];
                        d2 += grid[r + i][c + k - 1 - i];
                    }
                    if (d1 == target && d2 == target) return k;
                }
            }
        }
        return 1;
    }
};

