var largestMagicSquare = function(grid) {
    const m = grid.length, n = grid[0].length;
    const rowPref = Array.from({ length: m }, () => Array(n + 1).fill(0));
    const colPref = Array.from({ length: m + 1 }, () => Array(n).fill(0));

    for (let r = 0; r < m; ++r) {
        for (let c = 0; c < n; ++c) {
            rowPref[r][c + 1] = rowPref[r][c] + grid[r][c];
            colPref[r + 1][c] = colPref[r][c] + grid[r][c];
        }
    }

    for (let k = Math.min(m, n); k > 1; --k) {
        for (let r = 0; r <= m - k; ++r) {
            for (let c = 0; c <= n - k; ++c) {
                const target = rowPref[r][c + k] - rowPref[r][c];
                let valid = true;

                for (let i = 1; i < k; ++i) {
                    if (rowPref[r + i][c + k] - rowPref[r + i][c] !== target) {
                        valid = false;
                        break;
                    }
                }
                if (!valid) continue;

                for (let j = 0; j < k; ++j) {
                    if (colPref[r + k][c + j] - colPref[r][c + j] !== target) {
                        valid = false;
                        break;
                    }
                }
                if (!valid) continue;

                let d1 = 0, d2 = 0;
                for (let i = 0; i < k; ++i) {
                    d1 += grid[r + i][c + i];
                    d2 += grid[r + i][c + k - 1 - i];
                }
                if (d1 === target && d2 === target) return k;
            }
        }
    }
    return 1;
};
